var i=`0228-pasteis-de-nata`;var s=`world-0228`;var a=`PT`;var n=`southern-europe`;var r=8;var l=43;var o={en:`Pastéis de Nata`,ua:`Паштел-де-ната`};var u={en:`A traditional Portugal dish made with puff pastry, whole cow milk, lemon zest, egg yolk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: листкове тісто, цільне коров'яче молоко, цедра лимона, яєчний жовток. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Roll the puff pastry tightly into a log, slice into rounds and press each into a small tart mold, pushing pastry thin up the sides. Chill the shells.`,ua:`Щільно згорніть листкове тісто рулетом, наріжте кружальцями та розтисніть кожен у маленькій формі, витончуючи тісто вгору по бортах. Охолодіть заготовки.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[[`puff-pastry`,400,`g`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`whole-cow-milk`,420,`ml`],[`white-granulated-sugar`,170,`g`],[`ceylon-cinnamon`,1,`pcs`],[`lemon-zest`,5,`g`]]},{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:8,i:[[`egg-yolk`,6,`pcs`],[`all-purpose-flour`,30,`g`],[`cornstarch`,20,`g`]]},{en:`Fill the pastry cups three-quarters full and bake at 250–270°C until the pastry is crisp and the custard top shows dark caramelized spots; cool before unmolding.`,ua:`Наповніть формочки кремом на три чверті й випікайте при 250–270°C до хрусткості тіста й темних карамелізованих плям на поверхні; остудіть перед вийманням.`,t:[`high-temperature-roasting`,`baking`],m:15,i:[]}];var h={slug:i,id:s,country:`PT`,region:n,servings:8,minutes:43,title:o,text:u,steps:g};export{a as country,h as default,s as id,l as minutes,n as region,r as servings,i as slug,g as steps,u as text,o as title};